/* ================= ENVIRONMENT ================= */
Q.push(
{id:"ENV-E-01",mode:"easy",subj:"environment",topic:"Protected areas",type:"mcq",
 stem:"Kaziranga National Park is best known for which animal?",
 opts:["Asiatic lion","Snow leopard","Great one-horned rhinoceros","Nilgiri tahr"],ans:2,
 wn:["Asiatic lions live in the wild only in and around Gir, in Gujarat.", "Snow leopards live in the high Himalaya, such as Hemis in Ladakh — not Assam's floodplains.", null, "The Nilgiri tahr is a mountain goat of the southern Western Ghats, best known from Eravikulam in Kerala."],
 take:"Kaziranga (Assam): one-horned rhino · UNESCO site 1985 · tiger reserve 2006.",
 why:"Kaziranga in Assam holds about two-thirds of the world's greater one-horned rhinos and is a UNESCO World Heritage Site (1985). It was also declared a tiger reserve in 2006.",
 rev:"Shankar IAS, Environment — Protected Area Network",
 links:[WP("Kaziranga National Park","Kaziranga_National_Park")]},

{id:"ENV-E-02",mode:"easy",subj:"environment",topic:"International conventions",type:"mcq",
 stem:"The Montreal Protocol deals with:",
 opts:["Climate change and greenhouse gases","Trade in endangered species","Transboundary movement of hazardous waste","Ozone-depleting substances"],ans:3,
 wn:["Climate change and greenhouse gases come under the UNFCCC and its Paris Agreement.", "Trade in endangered species is regulated by CITES.", "Hazardous waste moving across borders is covered by the Basel Convention.", null],
 take:"Montreal = ozone · UNFCCC/Paris = climate · CITES = wildlife trade · Basel = hazardous waste.",
 why:"The Montreal Protocol (1987) phases out substances that damage the ozone layer, such as CFCs. Climate change falls under the UNFCCC and Paris Agreement, trade in endangered species under CITES, and hazardous waste under the Basel Convention.",
 rev:"Shankar IAS, Environment — International Environmental Conventions",
 links:[WP("Montreal Protocol","Montreal_Protocol"),{t:"UNEP Ozone Secretariat",u:"https://ozone.unep.org/"}]},

{id:"ENV-E-03",mode:"easy",subj:"environment",topic:"International conventions",type:"mcq",
 stem:"The Ramsar Convention is related to the conservation of:",
 opts:["Wetlands","Migratory species","Drylands and desertification","Endangered species in trade"],ans:0,
 wn:[null, "Migratory species come under the Bonn Convention (CMS).", "Drylands and desertification come under the UN Convention to Combat Desertification (UNCCD).", "International trade in endangered species comes under CITES."],
 take:"Ramsar (1971, Iran) = wetlands.",
 why:"The Ramsar Convention (1971, Ramsar, Iran) is for the conservation and wise use of wetlands. Migratory species fall under the Bonn Convention (CMS), desertification under the UNCCD, and wildlife trade under CITES.",
 rev:"Shankar IAS, Environment — Wetlands",
 links:[WP("Ramsar Convention","Ramsar_Convention"),{t:"Ramsar Convention Secretariat",u:"https://www.ramsar.org/"}]},

{id:"ENV-E-04",mode:"easy",subj:"environment",topic:"Species · Asiatic lion",type:"mcq",
 stem:"The only wild population of the Asiatic lion is found in:",
 opts:["Ranthambore","Kanha","Sundarbans","Gir"],ans:3,
 wn:["Ranthambore in Rajasthan is a tiger reserve; it has no wild lions.", "Kanha in Madhya Pradesh is known for tigers and the hard-ground barasingha.", "The Sundarbans are known for mangrove-dwelling tigers, not lions.", null],
 take:"Gir (Gujarat) = the only wild Asiatic lions.",
 why:"Asiatic lions survive in the wild only in the Gir forest and surrounding landscape of Saurashtra, Gujarat. Ranthambore is known for tigers, Kanha for the hard-ground barasingha, and the Sundarbans for mangrove tigers.",
 rev:"Shankar IAS, Environment — Protected Area Network",
 links:[WP("Gir National Park","Gir_National_Park")]},

{id:"ENV-E-05",mode:"easy",subj:"environment",topic:"Climate change",type:"mcq",
 stem:"Which gas is the largest contributor to human-caused global warming?",
 opts:["Methane","Carbon dioxide","Nitrous oxide","Water vapour"],ans:1,
 wn:["Methane traps more heat per molecule, but there's far less of it and it breaks down within about a decade.", null, "Nitrous oxide, mainly from fertilisers, is potent but a much smaller contributor.", "Water vapour amplifies warming as a feedback; human activity doesn't drive it directly."],
 take:"CO₂ is the biggest driver; methane is stronger per molecule but shorter-lived.",
 why:"Carbon dioxide from burning fossil fuels and land-use change is the largest contributor to human-caused warming. Methane traps far more heat per molecule but stays in the air for a much shorter time; water vapour acts mainly as a feedback rather than a direct driver.",
 rev:"Shankar IAS, Environment — Climate Change",
 links:[WP("Greenhouse gas","Greenhouse_gas")]},

{id:"ENV-E-06",mode:"easy",subj:"environment",topic:"Conservation bodies",type:"mcq",
 stem:"Which organisation publishes the Red List of Threatened Species?",
 opts:["UNEP","WWF","CITES","IUCN"],ans:3,
 wn:["UNEP is the UN's environment programme; it doesn't publish the Red List.", "WWF is a conservation charity; the Red List is the IUCN's.", "CITES is a treaty that regulates wildlife trade; its appendices aren't the Red List.", null],
 take:"IUCN Red List: Critically Endangered → Endangered → Vulnerable …",
 why:"The IUCN Red List assesses species into categories such as Critically Endangered, Endangered and Vulnerable. CITES regulates international wildlife trade; WWF is an NGO; UNEP is a UN programme.",
 rev:"Shankar IAS, Environment — Biodiversity",
 links:[WP("IUCN Red List","IUCN_Red_List")]},

{id:"ENV-E-07",mode:"easy",subj:"environment",topic:"Environmental movements",type:"mcq",
 stem:"The Chipko movement was mainly about:",
 opts:["Protecting forests from felling","Opposing a large dam","Banning wildlife hunting","Stopping mining in rivers"],ans:0,
 wn:[null, "Opposing a large dam was the Narmada Bachao Andolan, against the Sardar Sarovar dam.", "Hunting was banned through the Wildlife (Protection) Act, 1972; Chipko was about trees.", "Chipko began over trees allotted to outside contractors for felling, not over mining."],
 take:"Chipko (1973, Garhwal Himalaya): villagers hugged trees to stop felling.",
 why:"Chipko began in 1973 in the Garhwal Himalaya (now Uttarakhand), when villagers — many of them women — hugged trees to stop commercial felling. Chandi Prasad Bhatt, Sunderlal Bahuguna and Gaura Devi are associated with it. The Narmada Bachao Andolan was the anti-dam movement.",
 links:[WP("Chipko movement","Chipko_movement")]},

{id:"ENV-E-08",mode:"easy",subj:"environment",topic:"Ecosystems · Mangroves",type:"mcq",
 stem:"Mangroves are best described as:",
 opts:["Coniferous forests of the Himalaya","Grasslands of the Deccan plateau","Salt-tolerant trees of coastal intertidal zones","Dry deciduous forests of central India"],ans:2,
 wn:["Coniferous forests of pine, deodar and fir grow in the Himalaya's cooler, higher zones.", "The Deccan's grasslands are dry and inland; mangroves need salty coastal water.", null, "Dry deciduous forests, such as teak, shed their leaves in the dry season and grow inland."],
 take:"Mangroves: salt-tolerant, breathing roots, seeds sprout on the tree; Sundarbans is the largest.",
 why:"Mangroves grow in brackish, intertidal zones, with breathing roots (pneumatophores) and seeds that germinate while still on the tree (vivipary). The Sundarbans, shared by India and Bangladesh, is the largest mangrove forest; mangroves protect coasts from storm surges.",
 rev:"Shankar IAS, Environment — Mangroves",
 links:[WP("Mangrove","Mangrove")]},

{id:"ENV-E-09",mode:"easy",subj:"environment",topic:"Climate change · Paris Agreement",type:"mcq",
 stem:"The Paris Agreement aims to hold the rise in global average temperature to well below:",
 opts:["1 °C above pre-industrial levels","2 °C above pre-industrial levels","3 °C above pre-industrial levels","4 °C above pre-industrial levels"],ans:1,
 wn:["There's no 1 °C goal; the stretch target is to pursue efforts to limit warming to 1.5 °C.", null, "3 °C would be far beyond the Paris goal of well below 2 °C.", "4 °C is a high-emissions outcome, not any treaty's goal."],
 take:"Paris (COP21, 2015): well below 2 °C, pursue 1.5 °C; countries file NDCs.",
 why:"Adopted at COP21 in 2015, the Paris Agreement aims to keep warming well below 2 °C above pre-industrial levels and to pursue efforts to limit it to 1.5 °C. Countries set their own targets as Nationally Determined Contributions (NDCs).",
 rev:"Shankar IAS, Environment — Climate Change Organisations",
 links:[WP("Paris Agreement","Paris_Agreement")]},

{id:"ENV-E-10",mode:"easy",subj:"environment",topic:"Pollution · Biomagnification",type:"mcq",
 stem:"Which of the following is a non-biodegradable pollutant that builds up along food chains?",
 opts:["Vegetable waste","Sewage","DDT","Paper"],ans:2,
 wn:["Vegetable waste is broken down by microbes, so it doesn't build up in food chains.", "Sewage is biodegradable; microbes break it down, though it can strip oxygen from water.", null, "Paper is biodegradable: microbes break down its cellulose."],
 take:"Biomagnification: persistent chemicals like DDT concentrate up the food chain.",
 why:"DDT persists in the environment and its concentration increases at each level of the food chain (biomagnification) — famously thinning bird eggshells. Vegetable waste, sewage and paper are broken down by microbes.",
 rev:"Shankar IAS, Environment — Environmental Pollution",
 links:[WP("Biomagnification","Biomagnification")]},

{id:"ENV-X-01",mode:"exam",subj:"environment",topic:"Ozone · Kigali Amendment",type:"statements",
 stem:"Consider the following statements about the Kigali Amendment:",
 items:["It is an amendment to the Montreal Protocol.",
        "It aims to phase down hydrofluorocarbons (HFCs).",
        "HFCs are major ozone-depleting substances."],
 tail:"How many of the statements given above are correct?",
 opts:["None","Only one","Only two","All three"],ans:2,
 sv:[1, 1, 0],
 sr:["The Kigali Amendment (2016) amends the Montreal Protocol.", "It phases down hydrofluorocarbons (HFCs) step by step.", "HFCs don't deplete ozone; they are controlled because they are powerful greenhouse gases."],
 take:"HFCs don't harm ozone but are potent greenhouse gases → phased down by Kigali (2016).",
 why:"I and II are correct. HFCs replaced ozone-depleting CFCs and do not harm the ozone layer, but they are powerful greenhouse gases. That is why the 2016 Kigali Amendment brought them under the Montreal Protocol.",
 rev:"Shankar IAS, Environment — International Environmental Conventions",
 links:[{t:"Montreal Protocol (see Kigali Amendment)",u:"https://en.wikipedia.org/wiki/Montreal_Protocol"}]},

{id:"ENV-X-02",mode:"exam",subj:"environment",topic:"Protected areas",type:"match",
 stem:"Consider the following pairs:",
 heads:["Protected area","State"],
 pairs:[["Silent Valley National Park","Kerala"],["Simlipal National Park","Odisha"],["Bandipur National Park","Karnataka"],["Keoladeo National Park","Madhya Pradesh"]],
 tail:"Which of the pairs given above are correctly matched?",
 opts:["I, II and III only","III and IV only","I and IV only","I, II, III and IV"],ans:0,
 pv:[1, 1, 1, 0],
 pr:["Silent Valley National Park is in Kerala's Palakkad district.", "Simlipal National Park is in Odisha's Mayurbhanj district.", "Bandipur National Park is in Karnataka, part of the Nilgiri Biosphere Reserve.", "Keoladeo National Park, the former Bharatpur Bird Sanctuary, is in Rajasthan."],
 take:"Keoladeo (Bharatpur) = Rajasthan; Silent Valley = Kerala.",
 why:"Pair IV is wrong: Keoladeo (formerly Bharatpur Bird Sanctuary) is in Rajasthan; it is a UNESCO World Heritage Site and a Ramsar wetland. Silent Valley is known for tropical evergreen forest and the lion-tailed macaque.",
 rev:"Shankar IAS, Environment — Protected Area Network",
 links:[WP("Keoladeo National Park","Keoladeo_National_Park")]},

{id:"ENV-X-03",mode:"exam",subj:"environment",topic:"Biodiversity hotspots",type:"statements",
 stem:"Consider the following statements:",
 items:["India has parts of four of the world's biodiversity hotspots.",
        "The Western Ghats are a UNESCO World Heritage Site.",
        "The Andaman and Nicobar Islands do not fall in any biodiversity hotspot."],
 tail:"Which of the statements given above is/are correct?",
 opts:["I only","II and III only","I, II and III","I and II only"],ans:3,
 sv:[1, 1, 0],
 sr:["India has parts of four hotspots: the Himalaya, Indo-Burma, Western Ghats–Sri Lanka and Sundaland.", "The Western Ghats became a UNESCO World Heritage Site in 2012.", "The Nicobar Islands fall in Sundaland and the Andamans in Indo-Burma."],
 take:"India's hotspots: Himalaya, Indo-Burma, Western Ghats–Sri Lanka, Sundaland (Nicobar).",
 why:"India's four hotspots are the Himalaya, Indo-Burma, Western Ghats–Sri Lanka and Sundaland. The Nicobar Islands are part of Sundaland and the Andamans of Indo-Burma, so III is wrong. The Western Ghats became a World Heritage Site in 2012.",
 rev:"NCERT Class 12 Biology — Biodiversity and Conservation",
 links:[WP("Biodiversity hotspot","Biodiversity_hotspot")]},

{id:"ENV-X-04",mode:"exam",subj:"environment",topic:"Biosphere reserves",type:"statements",
 stem:"Consider the following statements about biosphere reserves in India:",
 items:["A biosphere reserve is divided into core, buffer and transition zones.",
        "The Nilgiri Biosphere Reserve was the first to be set up in India.",
        "All of India's biosphere reserves are part of UNESCO's World Network of Biosphere Reserves."],
 tail:"How many of the statements given above are correct?",
 opts:["Only one","Only two","All three","None"],ans:1,
 sv:[1, 1, 0],
 sr:["Biosphere reserves have a core zone, a buffer zone and an outer transition zone.", "The Nilgiri Biosphere Reserve, set up in 1986, was India's first.", "Only some of India's biosphere reserves are in UNESCO's World Network."],
 take:"Biosphere reserve zones: core → buffer → transition; Nilgiri (1986) was first.",
 why:"Nilgiri (1986) was India's first biosphere reserve, and all reserves follow the core–buffer–transition zoning. Only some of India's biosphere reserves are in UNESCO's World Network, so III is wrong.",
 rev:"Shankar IAS, Environment — Protected Area Network",
 links:[W("List of biosphere reserves in India","List of biosphere reserves in India")]},

{id:"ENV-X-05",mode:"exam",subj:"environment",topic:"Ecosystems · Coral reefs",type:"assertion",
 stem:"Consider the following statements:",
 s1:"Reef-building corals are mostly found in shallow, clear, warm tropical waters.",
 s2:"Reef-building corals depend on symbiotic algae (zooxanthellae) that need sunlight for photosynthesis.",
 ans:0,
 av:[1, 1, 1],
 ar:["Reef-building corals grow mostly in shallow, clear, warm tropical seas.", "Zooxanthellae living in coral tissue photosynthesise and supply most of the coral's food.", "Because the algae need light, reefs grow where sunlight reaches — shallow, clear water — so II explains I."],
 take:"Corals need sunlight because their algae (zooxanthellae) photosynthesise; heat stress → bleaching.",
 why:"Both are correct, and II explains I: the zooxanthellae living in coral tissue supply most of the coral's food through photosynthesis, so reefs grow where light penetrates — shallow, clear water. When stressed by heat, corals expel these algae and 'bleach'.",
 rev:"Shankar IAS, Environment — Coral Reefs",
 links:[WP("Coral reef","Coral_reef")]},

{id:"ENV-X-06",mode:"exam",subj:"environment",topic:"International conventions",type:"match",
 stem:"Consider the following pairs:",
 heads:["Convention","Subject"],
 pairs:[["CITES","International trade in endangered species"],["Bonn Convention","Migratory species of wild animals"],["Stockholm Convention","Persistent organic pollutants"],["Rotterdam Convention","Protection of the ozone layer"]],
 tail:"How many of the pairs given above are correctly matched?",
 opts:["Only one","Only two","Only three","All four"],ans:2,
 pv:[1, 1, 1, 0],
 pr:["CITES (1973) regulates international trade in endangered wild animals and plants.", "The Bonn Convention, or CMS (1979), protects migratory species of wild animals.", "The Stockholm Convention (2001) targets persistent organic pollutants such as DDT.", "The Rotterdam Convention covers trade in hazardous chemicals and pesticides; ozone is the Vienna Convention and Montreal Protocol."],
 take:"Rotterdam = prior informed consent for hazardous chemicals; Vienna = ozone layer.",
 why:"Pair IV is wrong: the Rotterdam Convention is about prior informed consent for trade in certain hazardous chemicals and pesticides. Ozone protection comes under the Vienna Convention and its Montreal Protocol.",
 rev:"Shankar IAS, Environment — International Environmental Conventions",
 links:[W("Rotterdam Convention","Rotterdam Convention")]},

{id:"ENV-X-07",mode:"exam",subj:"environment",topic:"Pollution · Eutrophication",type:"statements",
 stem:"With reference to eutrophication of water bodies, consider the following statements:",
 items:["It is caused by excess nutrients such as nitrates and phosphates.",
        "It often leads to algal blooms.",
        "It increases the dissolved oxygen available to fish."],
 tail:"Which of the statements given above is/are correct?",
 opts:["I and II only","II only","I and III only","I, II and III"],ans:0,
 sv:[1, 1, 0],
 sr:["Excess nutrients, mainly nitrates and phosphates from fertilisers and sewage, cause eutrophication.", "The extra nutrients feed rapid algal growth — algal blooms.", "When the algae die, their decay uses up dissolved oxygen, so fish can suffocate."],
 take:"Eutrophication: nutrients ↑ → algal bloom → decay uses oxygen → fish die.",
 why:"Fertiliser and sewage nutrients feed algal blooms; when the algae die, their decomposition uses up dissolved oxygen, which can kill fish. So III is wrong — eutrophication lowers dissolved oxygen.",
 rev:"Shankar IAS, Environment — Environmental Pollution",
 links:[WP("Eutrophication","Eutrophication")]},

{id:"ENV-X-08",mode:"exam",subj:"environment",topic:"Wildlife law · National parks",type:"statements",
 stem:"Under the Wildlife (Protection) Act, 1972, consider the following statements:",
 items:["Grazing of livestock is not permitted inside a national park.",
        "The boundaries of a national park can be altered only on the recommendation of the National Board for Wildlife.",
        "Wildlife sanctuaries have stricter protection than national parks."],
 tail:"How many of the statements given above are correct?",
 opts:["Only one","All three","Only two","None"],ans:2,
 cx:"Under the Wildlife (Protection) Act, 1972",
 sv:[1, 1, 0],
 sr:["The Act (Section 35) bans grazing of livestock inside a national park.", "A national park's boundaries can be altered only on the National Board for Wildlife's recommendation.", "It's the reverse: national parks are more strictly protected, and sanctuaries allow some regulated activities."],
 take:"National park > sanctuary in protection: no grazing; boundary change needs NBWL's recommendation.",
 why:"National parks are more strictly protected than sanctuaries — grazing is banned and their boundaries can be changed only on the National Board for Wildlife's recommendation. Sanctuaries allow some regulated activities, so III is wrong.",
 rev:"Shankar IAS, Environment — Protected Area Network",
 links:[W("Wildlife Protection Act, 1972","Wildlife Protection Act 1972")]},

{id:"ENV-X-09",mode:"exam",subj:"environment",topic:"Atmosphere · Ozone layer",type:"assertion",
 stem:"Consider the following statements:",
 s1:"Most of the Earth's ozone is found in the stratosphere.",
 s2:"Stratospheric ozone absorbs most of the Sun's infrared radiation.",
 ans:2,
 av:[1, 0, 0],
 ar:["About 90% of the atmosphere's ozone is in the stratosphere.", "Stratospheric ozone absorbs most of the Sun's harmful ultraviolet radiation, not infrared.", "Statement II is false, so it can't explain Statement I."],
 take:"Stratospheric ozone absorbs ultraviolet (UV), not infrared.",
 why:"About 90% of atmospheric ozone sits in the stratosphere, so I is correct. It shields life by absorbing most of the Sun's harmful ultraviolet radiation — not infrared — so II is incorrect.",
 rev:"NCERT Class 11, Fundamentals of Physical Geography — Composition and Structure of Atmosphere",
 links:[WP("Ozone layer","Ozone_layer")]},

{id:"ENV-X-10",mode:"exam",subj:"environment",topic:"Wetlands · Ramsar sites",type:"match",
 stem:"Consider the following pairs:",
 heads:["Ramsar site","State / UT"],
 pairs:[["Chilika Lake","Odisha"],["Loktak Lake","Manipur"],["Wular Lake","Jammu and Kashmir"],["Sambhar Lake","Gujarat"]],
 tail:"Which of the pairs given above are correctly matched?",
 opts:["I and II only","II and IV only","I, II, III and IV","I, II and III only"],ans:3,
 pv:[1, 1, 1, 0],
 pr:["Chilika, a large brackish-water lagoon, is in Odisha.", "Loktak Lake, with its floating phumdis, is in Manipur.", "Wular Lake, one of India's largest freshwater lakes, is in Jammu and Kashmir.", "Sambhar, India's largest inland salt lake, is in Rajasthan."],
 take:"Sambhar = Rajasthan (salt lake); Chilika (1981) was among India's first Ramsar sites.",
 why:"Pair IV is wrong: Sambhar, India's largest inland salt lake, is in Rajasthan. Chilika and Keoladeo were India's first Ramsar sites (1981); Loktak is known for its floating phumdis.",
 rev:"Shankar IAS, Environment — Wetlands",
 links:[W("List of Ramsar sites in India","List of Ramsar sites in India")]},

{id:"ENV-X-11",mode:"exam",subj:"environment",topic:"Species conservation · Tigers",type:"statements",
 stem:"Consider the following statements:",
 items:["Project Tiger was launched in 1973.",
        "The National Tiger Conservation Authority is a statutory body under the Wildlife (Protection) Act, 1972.",
        "The all-India tiger estimation is carried out every year."],
 tail:"How many of the statements given above are correct?",
 opts:["Only two","Only one","All three","None"],ans:0,
 sv:[1, 1, 0],
 sr:["Project Tiger was launched on 1 April 1973.", "A 2006 amendment to the Wildlife (Protection) Act made the NTCA a statutory body.", "The all-India tiger estimation is done every four years, not every year."],
 take:"Project Tiger 1973 · NTCA statutory (2006 amendment) · tiger estimation every 4 years.",
 why:"Project Tiger began in 1973, and the NTCA was given statutory status by a 2006 amendment to the Wildlife (Protection) Act. The all-India tiger estimation is done every four years, not annually, so III is wrong.",
 rev:"Shankar IAS, Environment — Animal Diversity of India (Project Tiger)",
 links:[WP("Project Tiger","Project_Tiger")]}
);

/* ---- geography.js ---- */
/* ================= GEOGRAPHY ================= */
Q.push(
{id:"GEO-E-01",mode:"easy",subj:"geography",topic:"Rivers · North India",type:"mcq",
 stem:"Which river is known as the 'Sorrow of Bihar'?",
 opts:["Damodar","Gandak","Son","Kosi"],ans:3,
 wn:["The Damodar was the 'Sorrow of Bengal', later tamed by the Damodar Valley Corporation's dams.", "The Gandak is a Himalayan tributary of the Ganga in Bihar, but the 'Sorrow of Bihar' is the Kosi.", "The Son is a south-bank tributary of the Ganga rising near Amarkantak, not known for shifting its course.", null],
 take:"Kosi = Sorrow of Bihar; Damodar = Sorrow of Bengal.",
 why:"The Kosi carries heavy silt from the Himalaya and often shifts its course, causing severe floods in north Bihar. The Damodar was called the 'Sorrow of Bengal'.",
 rev:"NCERT Class 11, India: Physical Environment — Drainage System",
 links:[WP("Kosi River","Kosi_River")]},

{id:"GEO-E-02",mode:"easy",subj:"geography",topic:"India's neighbours · Straits",type:"mcq",
 stem:"The Palk Strait separates India from:",
 opts:["Sri Lanka","Maldives","Myanmar","Indonesia"],ans:0,
 wn:[null, "The Maldives lie across the Eight Degree Channel from Minicoy in Lakshadweep.", "India and Myanmar share a land border; at sea, the Coco Channel lies between the Andamans and Myanmar's Coco Islands.", "The Great Channel separates Great Nicobar from Sumatra in Indonesia."],
 take:"Palk Strait: Tamil Nadu ↔ Sri Lanka · Ten Degree Channel: Andaman ↔ Nicobar.",
 why:"The Palk Strait lies between Tamil Nadu and northern Sri Lanka. Ram Setu (Adam's Bridge), a chain of shoals, lies at its southern end towards the Gulf of Mannar. The Ten Degree Channel separates the Andaman and Nicobar groups.",
 rev:"NCERT Class 11, India: Physical Environment — India: Location",
 links:[WP("Palk Strait","Palk_Strait")]},

{id:"GEO-E-03",mode:"easy",subj:"geography",topic:"India · Latitudes",type:"mcq",
 stem:"The Tropic of Cancer does NOT pass through which of these states?",
 opts:["Jharkhand","Tripura","Odisha","Mizoram"],ans:2,
 wn:["Jharkhand is one of the eight states the Tropic of Cancer crosses; it passes near Ranchi.", "Tripura is one of the eight states the Tropic of Cancer crosses.", null, "Mizoram is the easternmost of the eight states the Tropic of Cancer crosses."],
 take:"Tropic of Cancer: 8 states, Gujarat to Mizoram — not Odisha.",
 why:"The Tropic of Cancer passes through eight states: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura and Mizoram. Odisha lies entirely south of it.",
 rev:"NCERT Class 11, India: Physical Environment — India: Location",
 links:[WP("Tropic of Cancer","Tropic_of_Cancer")]},

{id:"GEO-E-04",mode:"easy",subj:"geography",topic:"Physiography · Peninsula",type:"mcq",
 stem:"Which is the highest peak in peninsular India?",
 opts:["Doddabetta","Mahendragiri","Anamudi","Kalsubai"],ans:2,
 wn:["Doddabetta (about 2,637 m) is the highest peak of the Nilgiris, a little lower than Anamudi.", "Mahendragiri (about 1,500 m) is an Eastern Ghats peak in Odisha.", null, "Kalsubai (about 1,646 m) is the highest peak in Maharashtra."],
 take:"Anamudi (~2,695 m, Kerala) = highest south of the Himalaya.",
 why:"Anamudi (about 2,695 m) in the Anaimalai Hills of Kerala is the highest peak south of the Himalaya. Doddabetta is the highest in the Nilgiris; Kalsubai is the highest in Maharashtra.",
 rev:"NCERT Class 11, India: Physical Environment — Structure and Physiography",
 links:[WP("Anamudi","Anamudi")]},

{id:"GEO-E-05",mode:"easy",subj:"geography",topic:"Rivers · Peninsula",type:"mcq",
 stem:"Which river is often called the 'Dakshin Ganga'?",
 opts:["Krishna","Godavari","Kaveri","Mahanadi"],ans:1,
 wn:["The Krishna is the second-largest east-flowing peninsular river, rising near Mahabaleshwar.", null, "The Kaveri is occasionally called this too, but NCERT and most references give the name to the Godavari.", "The Mahanadi rises in Chhattisgarh and forms a delta in Odisha; it isn't called the Dakshin Ganga."],
 take:"Godavari = Dakshin Ganga; largest peninsular river, rises at Trimbakeshwar (Nashik).",
 why:"The Godavari, about 1,465 km long, is the largest peninsular river. It rises near Trimbakeshwar in Nashik, Maharashtra, and flows east into the Bay of Bengal.",
 rev:"NCERT Class 11, India: Physical Environment — Drainage System",
 links:[WP("Godavari River","Godavari_River")]},

{id:"GEO-E-06",mode:"easy",subj:"geography",topic:"India · Extremities",type:"mcq",
 stem:"Which is the southernmost point of India?",
 opts:["Kanyakumari","Rameswaram","Port Blair","Indira Point"],ans:3,
 wn:["Kanyakumari is the southern tip of the mainland, not of all India.", "Rameswaram is an island off Tamil Nadu, north of Kanyakumari.", "Port Blair (now Sri Vijaya Puram) is in South Andaman, far north of Great Nicobar.", null],
 take:"Indira Point (Great Nicobar) = southernmost point; Kanyakumari = mainland's tip.",
 why:"Indira Point on Great Nicobar Island is India's southernmost point. Kanyakumari is the southern tip of the mainland.",
 rev:"NCERT Class 11, India: Physical Environment — India: Location",
 links:[W("Indira Point","Indira Point Great Nicobar")]},

{id:"GEO-E-07",mode:"easy",subj:"geography",topic:"India · States",type:"mcq",
 stem:"Which is the largest state of India by area?",
 opts:["Rajasthan","Madhya Pradesh","Maharashtra","Uttar Pradesh"],ans:0,
 wn:[null, "Madhya Pradesh is the second-largest state by area.", "Maharashtra is the third-largest state by area.", "Uttar Pradesh has the most people, but it's fourth by area."],
 take:"By area: Rajasthan > Madhya Pradesh > Maharashtra. Smallest state: Goa.",
 why:"Rajasthan is the largest state (about 3.42 lakh sq km), followed by Madhya Pradesh and Maharashtra. Goa is the smallest state.",
 rev:"NCERT Class 9, Contemporary India I — India: Size and Location",
 links:[WP("Rajasthan","Rajasthan")]},

{id:"GEO-E-08",mode:"easy",subj:"geography",topic:"Climate · Monsoon",type:"mcq",
 stem:"Most of India receives its rainfall from the south-west monsoon during:",
 opts:["December to February","March to May","June to September","October to November"],ans:2,
 wn:["December to February is the cold season; western disturbances bring only light rain to the north-west.", "March to May is the hot season, with only pre-monsoon showers such as mango showers and Kalbaisakhi.", null, "October–November is the retreating monsoon, which matters mainly for the Tamil Nadu coast."],
 take:"South-west monsoon: June–Sept. Tamil Nadu coast gets most rain Oct–Dec.",
 why:"The south-west monsoon (June–September) brings most of India's annual rainfall. The Tamil Nadu coast is an exception: it gets most of its rain from October to December, during the retreating (north-east) monsoon.",
 rev:"NCERT Class 11, India: Physical Environment — Climate",
 links:[W("Monsoon of South Asia","Monsoon of South Asia")]},

{id:"GEO-E-09",mode:"easy",subj:"geography",topic:"Boundaries",type:"mcq",
 stem:"Which line forms the boundary between India and Pakistan?",
 opts:["McMahon Line","Durand Line","Radcliffe Line","Line of Actual Control"],ans:2,
 wn:["The McMahon Line is the India–China boundary in the east, in Arunachal Pradesh.", "The Durand Line separates Pakistan and Afghanistan.", null, "The Line of Actual Control separates Indian- and Chinese-held areas, not India and Pakistan."],
 take:"Radcliffe: India–Pakistan (and Bangladesh) · McMahon: India–China (east) · Durand: Pakistan–Afghanistan.",
 why:"The Radcliffe Line (1947) defined the India–Pakistan boundary, and also the India–Bangladesh one. The McMahon Line is the India–China boundary in the east; the Durand Line separates Pakistan and Afghanistan.",
 rev:"NCERT Class 11, India: Physical Environment — India: Location",
 links:[WP("Radcliffe Line","Radcliffe_Line")]},

{id:"GEO-E-10",mode:"easy",subj:"geography",topic:"Deserts",type:"mcq",
 stem:"Which of these is a cold desert in India?",
 opts:["Thar Desert","Ladakh","Rann of Kutch","Deccan Plateau"],ans:1,
 wn:["The Thar, in Rajasthan, is a hot desert.", null, "The Rann of Kutch is a seasonal salt marsh in Gujarat, not a cold desert.", "The Deccan is a plateau of forests and farmland, not a desert."],
 take:"Ladakh = high-altitude cold desert in the Himalayan rain shadow; Thar = hot desert.",
 why:"Ladakh is a high-altitude cold desert lying in the rain shadow of the Great Himalaya, with very low rainfall. The Thar is a hot desert.",
 rev:"NCERT Class 11, India: Physical Environment — Structure and Physiography",
 links:[WP("Ladakh","Ladakh")]},

{id:"GEO-X-01",mode:"exam",subj:"geography",topic:"Rivers · West-flowing",type:"statements",
 stem:"Consider the following statements:",
 items:["The Narmada flows westward through a rift valley.",
        "The Tapi drains into the Arabian Sea.",
        "The Mahanadi drains into the Arabian Sea."],
 tail:"Which of the statements given above is/are correct?",
 opts:["I and II only","II only","I and III only","I, II and III"],ans:0,
 sv:[1, 1, 0],
 sr:["The Narmada flows west through a rift valley between the Vindhyas and the Satpuras.", "The Tapi flows west into the Arabian Sea at the Gulf of Khambhat, near Surat.", "The Mahanadi flows east into the Bay of Bengal, forming a delta in Odisha."],
 take:"Narmada and Tapi: west-flowing, rift valleys, estuaries (no deltas).",
 why:"The Narmada and Tapi are the main west-flowing peninsular rivers; they flow through rift valleys and form estuaries rather than deltas. The Mahanadi flows east into the Bay of Bengal, forming a delta in Odisha — so III is wrong.",
 rev:"NCERT Class 11, India: Physical Environment — Drainage System",
 links:[WP("Narmada River","Narmada_River")]},

{id:"GEO-X-02",mode:"exam",subj:"geography",topic:"Mountain passes",type:"match",
 stem:"Consider the following pairs:",
 heads:["Mountain pass","State / UT"],
 pairs:[["Shipki La","Himachal Pradesh"],["Nathu La","Arunachal Pradesh"],["Bomdi La","Arunachal Pradesh"],["Zoji La","Uttarakhand"]],
 tail:"How many of the pairs given above are correctly matched?",
 opts:["Only one","Only two","Only three","All four"],ans:1,
 pv:[1, 0, 1, 0],
 pr:["Shipki La is in Himachal Pradesh, where the Sutlej enters India.", "Nathu La is in Sikkim, on the old trade route to Tibet.", "Bomdi La is in Arunachal Pradesh, on the road to Tawang.", "Zoji La is in Ladakh, on the Srinagar–Leh road — not Uttarakhand."],
 take:"Nathu La = Sikkim · Zoji La = Srinagar–Leh · Shipki La = where the Sutlej enters India.",
 why:"Pairs II and IV are wrong. Nathu La is in Sikkim, on the old trade route to Tibet. Zoji La lies on the Srinagar–Leh route, linking the Kashmir Valley with Ladakh. Shipki La (Himachal) is where the Sutlej enters India; Bomdi La is in Arunachal Pradesh.",
 rev:"NCERT Class 11, India: Physical Environment — Structure and Physiography",
 links:[WP("Zoji La","Zoji_La")]},

{id:"GEO-X-03",mode:"exam",subj:"geography",topic:"Soils",type:"statements",
 stem:"Consider the following statements about soils of India:",
 items:["Black soils have poor moisture-retention capacity.",
        "Laterite soils develop in areas of high temperature and heavy rainfall due to intense leaching.",
        "Alluvial soils are generally rich in phosphorus but poor in potash."],
 tail:"How many of the statements given above are correct?",
 opts:["Only one","Only two","All three","None"],ans:0,
 sv:[0, 1, 0],
 sr:["Black (regur) soils hold moisture well, which is why they suit cotton.", "Laterite soils form under high heat and heavy rain, which leach out silica and leave iron and aluminium behind.", "It's the reverse: alluvial soils are generally rich in potash but poor in phosphorus."],
 take:"Black soil holds moisture (cotton) · alluvial: rich in potash, poor in phosphorus.",
 why:"Only statement II is correct. Black (regur) soils hold moisture well, which suits cotton. Alluvial soils are generally rich in potash but poor in phosphorus — the reverse of statement III.",
 rev:"NCERT Class 10, Contemporary India II — Resources and Development",
 links:[WP("Laterite","Laterite")]},

{id:"GEO-X-04",mode:"exam",subj:"geography",topic:"Rivers · Himalayan",type:"statements",
 stem:"Consider the following statements about Himalayan rivers:",
 items:["The Indus rises near Lake Mansarovar in Tibet.",
        "The Brahmaputra enters India through Arunachal Pradesh.",
        "The Ganga is formed by the confluence of the Bhagirathi and the Alaknanda at Devprayag."],
 tail:"How many of the statements given above are correct?",
 opts:["Only one","Only two","All three","None"],ans:2,
 sv:[1, 1, 1],
 sr:["The Indus rises in Tibet, near Lake Mansarovar.", "The Brahmaputra (the Tsangpo in Tibet) enters India in Arunachal Pradesh as the Siang or Dihang.", "The Bhagirathi and the Alaknanda meet at Devprayag to form the Ganga."],
 take:"Indus: near Mansarovar · Brahmaputra (Siang/Dihang) enters via Arunachal · Ganga: Devprayag.",
 why:"All three are correct. The Indus rises in Tibet near Lake Mansarovar; the Brahmaputra (Tsangpo in Tibet) enters India in Arunachal Pradesh as the Siang/Dihang; the Bhagirathi and Alaknanda meet at Devprayag to form the Ganga.",
 rev:"NCERT Class 11, India: Physical Environment — Drainage System",
 links:[W("Indus River","Indus River")]},

{id:"GEO-X-05",mode:"exam",subj:"geography",topic:"Climate · Orographic rain",type:"assertion",
 stem:"Consider the following statements:",
 s1:"The western coast of India receives heavy rainfall during the south-west monsoon.",
 s2:"The Western Ghats force the moist monsoon winds to rise and cool, causing orographic rainfall on the windward side.",
 ans:0,
 av:[1, 1, 1],
 ar:["The west coast is among India's wettest regions in June–September.", "Moist winds forced up the Western Ghats cool and shed rain on the windward side — orographic rainfall.", "That forced ascent is why the coast gets so much rain, so II explains I."],
 take:"Western Ghats → orographic rain on the windward coast; rain shadow on the Deccan side.",
 why:"Both are correct, and II explains I: the Arabian Sea branch of the monsoon hits the Western Ghats, rises, cools and sheds heavy rain on the coast, leaving a rain-shadow area on the leeward (eastern) side.",
 rev:"NCERT Class 11, India: Physical Environment — Climate",
 links:[W("Orographic lift","Orographic lift rainfall")]},

{id:"GEO-X-06",mode:"exam",subj:"geography",topic:"Hill ranges",type:"match",
 stem:"Consider the following pairs:",
 heads:["Hills","State"],
 pairs:[["Garo Hills","Meghalaya"],["Mikir Hills","Assam"],["Cardamom Hills","Kerala"],["Mahadeo Hills","Odisha"]],
 tail:"Which of the pairs given above are correctly matched?",
 opts:["I and II only","I, II and III only","II and IV only","I, II, III and IV"],ans:1,
 pv:[1, 1, 1, 0],
 pr:["The Garo Hills are in western Meghalaya.", "The Mikir Hills (Karbi Anglong) are in Assam.", "The Cardamom Hills run through Kerala, along its border with Tamil Nadu.", "The Mahadeo Hills are part of the Satpuras in Madhya Pradesh, around Pachmarhi."],
 take:"Mahadeo Hills = Madhya Pradesh (Satpura; Pachmarhi). Garo–Khasi–Jaintia = Meghalaya.",
 why:"Pair IV is wrong: the Mahadeo Hills are part of the Satpura range in Madhya Pradesh (Pachmarhi lies in them). The Cardamom Hills lie along the Kerala–Tamil Nadu border; the Mikir (Karbi Anglong) Hills are in Assam.",
 rev:"NCERT Class 11, India: Physical Environment — Structure and Physiography",
 links:[W("Mahadeo Hills","Mahadeo Hills")]},

{id:"GEO-X-07",mode:"exam",subj:"geography",topic:"Climatology · Cyclones",type:"statements",
 stem:"With reference to tropical cyclones, consider the following statements:",
 items:["In the Northern Hemisphere, they rotate anticlockwise.",
        "They form over warm seas, typically with surface temperatures above about 26–27 °C.",
        "They usually form within 5° of the Equator."],
 tail:"Which of the statements given above is/are correct?",
 opts:["I only","II and III only","I, II and III","I and II only"],ans:3,
 sv:[1, 1, 0],
 sr:["The Coriolis force makes Northern Hemisphere cyclones spin anticlockwise.", "They draw their energy from warm seas, typically above about 26–27 °C.", "The Coriolis force is too weak within about 5° of the Equator, so cyclones rarely form there."],
 take:"Cyclones: warm seas (~27 °C+), need Coriolis force → don't form right at the Equator.",
 why:"Cyclones need warm water for energy and the Coriolis force to spin; the Coriolis force is too weak near the Equator, so they rarely form within about 5° of it — III is wrong. In the Northern Hemisphere they rotate anticlockwise.",
 rev:"NCERT Class 11, Fundamentals of Physical Geography — Atmospheric Circulation and Weather Systems",
 links:[WP("Tropical cyclone","Tropical_cyclone")]},

{id:"GEO-X-08",mode:"exam",subj:"geography",topic:"World geography · Straits",type:"match",
 stem:"Consider the following pairs:",
 heads:["Strait","Connects"],
 pairs:[["Strait of Malacca","Andaman Sea and South China Sea"],["Strait of Hormuz","Persian Gulf and Gulf of Oman"],["Bab-el-Mandeb","Red Sea and Gulf of Aden"],["Strait of Gibraltar","Black Sea and Mediterranean Sea"]],
 tail:"How many of the pairs given above are correctly matched?",
 opts:["Only one","Only two","Only three","All four"],ans:2,
 pv:[1, 1, 1, 0],
 pr:["The Strait of Malacca links the Andaman Sea with the South China Sea.", "The Strait of Hormuz links the Persian Gulf with the Gulf of Oman.", "Bab-el-Mandeb links the Red Sea with the Gulf of Aden.", "Gibraltar links the Atlantic and the Mediterranean; the Black Sea reaches the Mediterranean through the Bosporus and Dardanelles."],
 take:"Gibraltar: Atlantic ↔ Mediterranean · Bosporus: Black Sea side.",
 why:"Pair IV is wrong: the Strait of Gibraltar connects the Atlantic Ocean and the Mediterranean. The Black Sea connects to the Mediterranean through the Bosporus, the Sea of Marmara and the Dardanelles.",
 rev:"Atlas practice — world straits and chokepoints",
 links:[WP("Strait of Malacca","Strait_of_Malacca")]},

{id:"GEO-X-09",mode:"exam",subj:"geography",topic:"Islands",type:"statements",
 stem:"Consider the following statements:",
 items:["The Lakshadweep islands are of coral origin.",
        "The Andaman and Nicobar Islands are an extension of the Arakan Yoma mountain range.",
        "Barren Island, India's only active volcano, is part of Lakshadweep."],
 tail:"How many of the statements given above are correct?",
 opts:["None","Only one","Only two","All three"],ans:2,
 sv:[1, 1, 0],
 sr:["Lakshadweep is made of coral atolls and reefs.", "The Andaman and Nicobar Islands are the peaks of a submerged extension of the Arakan Yoma.", "Barren Island is in the Andaman Sea, north-east of Port Blair — not in Lakshadweep."],
 take:"Lakshadweep = coral · Andaman–Nicobar = submerged Arakan Yoma · Barren Island = Andaman Sea.",
 why:"Lakshadweep consists of coral atolls, and the Andaman and Nicobar Islands are the peaks of a submerged extension of the Arakan Yoma. Barren Island lies in the Andaman Sea, not Lakshadweep — so III is wrong.",
 rev:"NCERT Class 11, India: Physical Environment — Structure and Physiography",
 links:[WP("Barren Island","Barren_Island")]},

{id:"GEO-X-10",mode:"exam",subj:"geography",topic:"Climate · North-east monsoon",type:"assertion",
 stem:"Consider the following statements:",
 s1:"Chennai receives most of its annual rainfall during the south-west monsoon.",
 s2:"The Tamil Nadu coast lies in the rain-shadow area of the Arabian Sea branch of the south-west monsoon.",
 ans:3,
 av:[0, 1, 0],
 ar:["Chennai gets most of its rain from October to December, from the north-east (retreating) monsoon.", "The Arabian Sea branch drops its rain on the Western Ghats, leaving the Tamil Nadu coast in rain shadow.", "Statement I is false, so Statement II can't explain it."],
 take:"Chennai's rain peaks Oct–Dec (north-east / retreating monsoon).",
 why:"Statement I is incorrect: Chennai gets most of its rain from October to December. Statement II is correct — the Arabian Sea branch drops its rain on the Western Ghats, and the Bay of Bengal branch runs parallel to the Tamil Nadu coast, so the coast stays relatively dry in June–September.",
 rev:"NCERT Class 11, India: Physical Environment — Climate",
 links:[W("Climate of Tamil Nadu","Climate of Tamil Nadu north-east monsoon")]},

{id:"GEO-X-11",mode:"exam",subj:"geography",topic:"Waterfalls",type:"match",
 stem:"Consider the following pairs:",
 heads:["Waterfall","River"],
 pairs:[["Jog Falls","Sharavathi"],["Dudhsagar Falls","Mandovi"],["Hogenakkal Falls","Kaveri"],["Athirappilly Falls","Godavari"]],
 tail:"Which of the pairs given above are correctly matched?",
 opts:["I, II and III only","I and II only","III and IV only","I, II, III and IV"],ans:0,
 pv:[1, 1, 1, 0],
 pr:["Jog Falls, in Karnataka, is on the Sharavathi.", "Dudhsagar Falls, on the Goa–Karnataka border, is on the Mandovi.", "Hogenakkal Falls is on the Kaveri, at the Tamil Nadu–Karnataka border.", "Athirappilly Falls, in Kerala, is on the Chalakudy river, not the Godavari."],
 take:"Athirappilly = Chalakudy river (Kerala). Jog = Sharavathi · Dudhsagar = Mandovi · Hogenakkal = Kaveri.",
 why:"Pair IV is wrong: Athirappilly Falls is on the Chalakudy river in Kerala. The other three are correct.",
 rev:"Atlas practice — peninsular rivers",
 links:[W("Athirappilly Falls","Athirappilly Falls")]}
);

